    ('ad605739-5499-4bbd-8a9f-448225caff56'::uuid, 'wikidata_qid', 'Q1058412', NULL, 'external-id:9f8887a3e75c8c47df3eb9d536d270e4278cdc95d92695769d42e0308fcd8469-rollback', 'EXT/wikidata_qid', 'two_source', '[{"source": "source-url split 2026-09-23 (wave 4)", "quote": "https://en.wikipedia.org/wiki/Chacmultun: resolve_titles, the path of refresh_site_external_ids (2026-09-23T11:38:14Z): page ''Chacmultun'', item Q1058412", "url": null}, {"source": "source-url split 2026-09-23 (wave 4)", "quote": "no other curated site carries Q1058412 (production, 2026-09-23T11:38:12Z)", "url": null}]'::jsonb),
