    ('8e625e19-eeb1-4813-8244-14ec448d7440'::uuid, 'wikidata_qid', 'Q13518345', NULL, 'external-id:ca3149fd034f5499264ade6fab763f23777d53745de6f3fc8f8e9f1cf21a3a19-rollback', 'EXT/wikidata_qid', 'two_source', '[{"source": "source-url split 2026-09-23 (wave 4)", "quote": "https://en.wikipedia.org/wiki/Chact%C3%BAn: resolve_titles, the path of refresh_site_external_ids (2026-09-23T11:38:14Z): page ''Chactún'', item Q13518345", "url": null}, {"source": "source-url split 2026-09-23 (wave 4)", "quote": "no other curated site carries Q13518345 (production, 2026-09-23T11:38:12Z)", "url": null}]'::jsonb),
    ('b7020e91-a80b-46cc-8624-878be1713336'::uuid, 'enwiki_title', 'Chalcatzingo', NULL, 'external-id:4b19e5201dd44b667524d15dcc3a216026d13c76d41cbbb7f4f73340322a5db1-rollback', 'EXT/enwiki_title', 'two_source', '[{"source": "source-url split 2026-09-23 (wave 4)", "quote": "https://en.wikipedia.org/wiki/Chalcatzingo: resolve_titles, the path of refresh_site_external_ids (2026-09-23T11:38:14Z): page ''Chalcatzingo'', item Q1059465", "url": null}]'::jsonb),
